    juntas_masculinas       = EXCLUDED.juntas_masculinas,
    total_juntas            = EXCLUDED.total_juntas,
    junta_inicial_femenina  = EXCLUDED.junta_inicial_femenina,
    junta_final_femenina    = EXCLUDED.junta_final_femenina,
    junta_inicial_masculina = EXCLUDED.junta_inicial_masculina,
    junta_final_masculina   = EXCLUDED.junta_final_masculina,
    numero_electores        = EXCLUDED.numero_electores,
    fecha_modificacion      = now();

DO $$
BEGIN
    IF (SELECT count(*) FROM public.recinto_electoral r
          JOIN public.parroquia p ON p.id = r.parroquia_id
         WHERE p.codigo_provincia = '10') <> 125 THEN
        RAISE EXCEPTION 'La carga de recintos de Imbabura no está completa';
    END IF;
END $$;

COMMIT;
